#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""Compare this notebook with the template it came from: the mechanical half
of the update skill (.claude/notebook/upstream.md).

  fetch [<url>]            fetch the template's newest commit; the URL defaults to TEMPLATE
  status [--at C]          each generic file against the template, and the skeletons changed upstream
  log [--since C]          the template's commits since C, each file marked generic, skeleton or the template's own
  skeleton [<path>] [--since C] [--to C]
                           what changed upstream in each skeleton, base to head unless told, to adapt by hand
  diff <path> [--at C]     the template's version at C against this notebook's
  take <path> [--at C]     replace a generic file with the template's version at C (default: head)
  record [C]               note C as the commit the generic files are level with (default: head)
  update [--to C]          after the first update: take every generic file up to C (default: head),
                           record it, and list the skeletons left to adapt
  verify [--staged]        refuse a generic file holding text the template never had
  install-hook             make `verify --staged` this checkout's pre-commit hook: the guard

C is a template commit: a sha, or `head` for the newest fetched. Where it is
left out it is TEMPLATE_COMMIT in notebook_config.py, the recorded base.
Without a recorded base, `status` finds one per file. This reports and copies;
every judgement is the skill's.
"""
import ast, difflib, os, pathlib, re, subprocess, sys

VAULT = pathlib.Path(__file__).resolve().parents[1]
REF = "refs/template/head"       # the fetched template, kept apart from the notebook's own refs
MANIFEST = ".claude/notebook/manifest.txt"
CONFIG = ".scripts/notebook_config.py"
# The update's own machinery, which a notebook older than it takes at the
# newest commit before anything else (upstream.md): it says nothing about the base.
OWN = {".scripts/upstream.py", ".scripts/checkout.py", ".claude/notebook/upstream.md", MANIFEST,
       ".claude/skills/update/SKILL.md"}
GUARD = "# notebook guard"
HOOK = f"""#!/bin/sh
{GUARD}, installed by upstream.py: a generic file holds only the template's
# text (.claude/notebook/upstream.md, "The guard").
exec python3 -I "$(git rev-parse --show-toplevel)/.scripts/upstream.py" verify --staged
"""


def git(*args, check=True, timeout=None, env=None):
    try:
        r = subprocess.run(["git", "-C", str(VAULT), *args], capture_output=True, timeout=timeout,
                           env={**os.environ, **env} if env else None)
    except subprocess.TimeoutExpired:
        sys.exit(f"git {args[0]} gave no answer in {timeout}s")
    if check and r.returncode:
        sys.exit(r.stderr.decode().strip() or f"git {args[0]} failed")
    return r

def commit(c):
    """A template commit's full sha. `head` is the newest fetched."""
    r = git("rev-parse", "--verify", "--quiet", (REF if c == "head" else c) + "^{commit}", check=False)
    if r.returncode:
        sys.exit(f"not a fetched template commit: {c} - run `fetch` first")
    return r.stdout.decode().strip()

def settings(text):
    """A config's literal settings and the functions it defines, parsed rather
    than imported: a notebook from before the config has none, and `record`
    rewrites it in the same second a later command reads it, which a stale
    bytecode cache would miss."""
    out = {}
    for node in ast.parse(text or "").body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            try:
                out[node.targets[0].id] = ast.literal_eval(node.value)
            except ValueError:
                out[node.targets[0].id] = None
        elif isinstance(node, ast.FunctionDef):
            out[node.name] = None
    return out

def config():
    p = VAULT / CONFIG
    return settings(p.read_text(encoding="utf-8")) if p.exists() else {}

def recorded():
    c = config().get("TEMPLATE_COMMIT")
    return commit(c) if c else None

def blob(c, path):
    r = git("show", f"{c}:{path}", check=False)
    return r.stdout if r.returncode == 0 else None

def mine(path):
    p = VAULT / path
    return p.read_bytes() if p.is_file() else None

def tree(c):
    return set(git("ls-tree", "-r", "--name-only", c).stdout.decode().split("\n")) - {""}

_CHOICES = {}

def manifest(c):
    """[(kind, path)] from the template's manifest at c. A `choice` is a
    generic file whose text comes from a source the notebook's setting picks
    (`choices`); everything else about it is a generic file's."""
    text = blob(c, MANIFEST)
    if text is None:
        sys.exit(f"the template at {c[:7]} has no {MANIFEST}")
    entries, picks = [], {}
    for l in text.decode().splitlines():
        f = l.split()
        if not f or l.startswith("#"):
            continue
        if f[0] == "choice" and len(f) >= 3:
            entries.append(("generic", f[1]))
            picks[f[1]] = (f[2], f[3] if len(f) > 3 else None)
        else:
            entries.append(tuple(f[:2]))
    _CHOICES[c] = picks
    return entries

def choices(c=None):
    """{file: (source pattern, default)} - the newest fetched manifest's."""
    c = c or commit("head")
    if c not in _CHOICES:
        manifest(c)
    return _CHOICES[c]

def source(path):
    """The template's path for a notebook's file: the file itself, or for a
    choice the source its setting names - or the manifest's default, for a
    notebook that names none."""
    pick = choices().get(path)
    if not pick:
        return path
    pattern, default = pick
    return pattern.format(**{v: config().get(v) or default for v in re.findall(r"\{(\w+)\}", pattern)})

def unset():
    """[(setting, default)] for each choice this notebook's config does not name."""
    return [(v, default) for pattern, default in choices().values()
            for v in re.findall(r"\{(\w+)\}", pattern) if not config().get(v)]

def sources():
    """The folders the choices' sources live in: a notebook never holds them."""
    return {os.path.dirname(pattern) + "/" for pattern, _ in choices().values()}

def tblob(c, path):
    """A notebook file's text in the template at c - its source's, for a choice."""
    return blob(c, source(path))

def kind(path, entries):
    """generic, skeleton, or None for the template's own: the longest entry matching."""
    hits = [(len(p), k) for k, p in entries if path == p or (p.endswith("/") and path.startswith(p))]
    k = max(hits)[1] if hits else None
    return None if k == "own" else k

def here_as(path):
    """What this notebook calls a template skeleton (SKELETONS in the config),
    or None where it was dropped. Unmapped, it keeps the template's name."""
    m = config().get("SKELETONS") or {}
    for k in sorted(m, key=len, reverse=True):
        if path == k or (k.endswith("/") and path.startswith(k)):
            return None if m[k] is None else m[k] + path[len(k):]
    return path

def changes(a, b):
    """[(status, old, new)] between two template commits, renames and copies
    found - a skeleton renamed upstream is still the same skeleton."""
    out = []
    for l in git("diff", "-M", "-C", "--name-status", a, b).stdout.decode().splitlines():
        f = l.split("\t")
        out.append((f[0][0], f[1], f[-1]))
    return out

def skeleton_changes(base, head, entries):
    return [(s, old, new) for s, old, new in changes(base, head)
            if kind(new, entries) == "skeleton" or (s == "D" and kind(old, entries) == "skeleton")]

def text(data):
    return (data or b"").decode(errors="replace").splitlines()

def changed_lines(a, b):
    return sum(1 for l in difflib.unified_diff(text(a), text(b), lineterm="", n=0)
               if l[:1] in "+-" and not l.startswith(("+++", "---")))

def short(c):
    return git("log", "-1", "--format=%h %s", c).stdout.decode().strip()[:72]


def template_blobs(f):
    """Every text the template has given a generic file, from the recorded
    base - or its beginning, with none recorded - to the newest fetched."""
    base, f = recorded(), source(f)
    cs = git("log", "--format=%H", f"{base}..{REF}" if base else REF, "--", f).stdout.decode().split()
    out = set()
    for c in cs + ([base] if base else []):
        r = git("rev-parse", "--verify", "--quiet", f"{c}:{f}", check=False)
        if r.returncode == 0:
            out.add(r.stdout.decode().strip())
    return out

def hook_path():
    p = pathlib.Path(git("rev-parse", "--git-path", "hooks/pre-commit").stdout.decode().strip())
    return p if p.is_absolute() else VAULT / p

def guarded():
    p = hook_path()
    return p.exists() and GUARD in p.read_text(errors="replace")


# ---------------------------------------------------------------- commands
def fetch(url=None, quiet=False):
    """Fetch the template's newest commit. Quiet is for when no one is there to
    answer a prompt - an open or a close setting up the guard - so it never
    asks for credentials and gives up after half a minute rather than hang."""
    url = url or config().get("TEMPLATE") or \
          git("config", "--get", "notebook.template", check=False).stdout.decode().strip()
    if not url:
        sys.exit("no template URL: give one, and `record` keeps it as TEMPLATE")
    git("fetch", "--quiet", "--no-tags", url, "HEAD",
        **({"timeout": 30, "env": {"GIT_TERMINAL_PROMPT": "0", "GCM_INTERACTIVE": "never"}} if quiet else {}))
    git("update-ref", REF, "FETCH_HEAD")
    git("config", "notebook.template", url)
    print(f"template {short(REF)}\n  from {url}")

def status(at=None):
    head = commit("head")
    entries = manifest(head)
    base = commit(at) if at else recorded()
    files = {f for f in tree(head) | (tree(base) if base else set()) if kind(f, entries) == "generic"} \
        | set(choices(head))
    for k, p in entries:          # a file in a generic folder that the template never had
        if k == "generic" and p.endswith("/") and (VAULT / p).is_dir():
            files |= {r for q in (VAULT / p).rglob("*") if q.is_file() and "__pycache__" not in q.parts
                      and kind(r := str(q.relative_to(VAULT)), entries) == "generic"}
    print(f"base     {short(base) if base else 'none recorded - found per file'}")
    print(f"head     {short(head)}\n")
    order = git("rev-list", "--reverse", REF).stdout.decode().split()     # oldest first
    candidates = None
    for f in sorted(files):
        here, then, now = mine(f), tblob(base, f) if base else None, tblob(head, f)
        if base:
            if here is None:
                state = "new upstream" if then is None else "missing here"
            elif then is None:
                later = _ahead(base, f, here)
                state = f"ahead: level with {later[:7]}" if later else \
                        "only here" if now is None else "here, but not at the base"
            elif here == then:
                state = "level" + ("" if then == now else ", changed upstream since")
            elif (later := _ahead(base, f, here)):
                state = f"ahead: level with {later[:7]}"
            else:
                state = f"drifted, {changed_lines(then, here)} lines" + \
                        ("" if then == now else ", and changed upstream since")
        else:
            state, span = _found(f, here, order)
            if f in OWN:
                state += "   (the update's own - leave out of the base)"
            elif span is not None:
                candidates = span if candidates is None else candidates & span
        print(f"  {state:<48} {f}")
    if not base and candidates is not None:
        cs = [c for c in order if c in candidates]
        print("\ncandidate base: " + ("none - no commit has every matching file level" if not cs else
              short(cs[0]) if len(cs) == 1 else f"{short(cs[0])}  ...  {short(cs[-1])}  ({len(cs)} commits)"))
    if base:
        moved = skeleton_changes(base, head, entries)
        if moved:
            print("\nskeletons changed upstream since the base - `skeleton` shows each; adapt by hand into:")
            for s, old, new in moved:
                mapped = here_as(new)
                into = "(dropped here)" if mapped is None else mapped + \
                       ("" if (VAULT / mapped).exists() else "   - not here: map it in SKELETONS")
                print(f"  {new + (f' (from {old})' if old != new else ''):<48} {into}")
    have, want = config(), settings((blob(head, CONFIG) or b"").decode())
    missing = sorted(set(want) - set(have))
    if missing:
        print(f"\n{CONFIG}: the template's has these and this notebook's does not: {', '.join(missing)}")
    for v, default in unset():
        print(f"\n{v} is not set in {CONFIG}: taken as {default}, the manifest's default")
    session = (VAULT / "CLAUDE.md").read_text(encoding="utf-8") if (VAULT / "CLAUDE.md").exists() else ""
    for pattern, default in choices().values():
        for v in re.findall(r"\{(\w+)\}", pattern):
            said = re.search(rf"\*\*{v.capitalize()}: (\w+)\*\*", session)
            if said and said.group(1).lower() != (config().get(v) or default):
                print(f"\nCLAUDE.md names {v.lower()} {said.group(1)}, but this notebook holds "
                      f"{config().get(v) or default}: bring the line level, since every session reads it")
    held = [str(q.relative_to(VAULT)) for d in sources() if (VAULT / d).is_dir()
            for q in (VAULT / d).rglob("*") if q.is_file()]
    if held:
        print("\nthe template's sources, which a notebook never holds: " + ", ".join(held))
    if base and not guarded():
        print("\nthis checkout has no guard: `checkout.py`")

def _ahead(base, f, here):
    """The newest commit after the base that this file is level with: taken
    ahead of the base on purpose, for an outlet only that commit has."""
    for c in git("log", "--format=%H", f"{base}..{REF}", "--", source(f)).stdout.decode().split():
        if tblob(c, f) == here:
            return c
    return None

def _found(f, here, order):
    """With no recorded base: the range of template commits this file is level
    with - from the commit that made it so, until the next one to change it -
    or the nearest when it matches none. Returns (state, the range as a set
    of commits, or None when it says nothing about the base)."""
    if here is None:
        return "missing here", None
    history = git("log", "--format=%H", REF, "--", source(f)).stdout.decode().split()   # newest first
    if not history:
        return "only here", None
    best = None
    for i, c in enumerate(history):
        then = tblob(c, f)
        if then == here:
            end = order.index(history[i - 1]) if i else len(order)
            span = set(order[order.index(c):end])
            return (f"level from {c[:7]} to head" if i == 0 else
                    f"level from {c[:7]}, until {history[i - 1][:7]}"), span
        n = changed_lines(then, here)
        if best is None or n < best[0]:
            best = (n, c)
    return f"drifted, nearest {best[1][:7]} by {best[0]} lines", None

def log(since=None):
    since = commit(since) if since else recorded()
    if not since:
        sys.exit("no base recorded: say where to start with --since")
    entries = manifest(commit("head"))
    for line in git("log", "--reverse", "--format=%H %s", f"{since}..{REF}").stdout.decode().splitlines():
        c, subject = line.split(" ", 1)
        by = {}
        mine_of = {source(f): f for f in choices()}
        for s, old, new in changes(c + "^", c):
            if new in mine_of:
                by.setdefault("generic", []).append(f"{mine_of[new]} (from {new})")
                continue
            by.setdefault(kind(new, entries) or "template's own", []).append(
                new if old == new else f"{new} (from {old})")
        reach = set(by) - {"template's own"}
        print(f"{c[:7]} {subject}" + ("" if reach else "   (the template's own - reaches no notebook)"))
        for k in ("generic", "skeleton", "template's own"):
            if k in by:
                print(f"    {k:<15} {', '.join(by[k])}")

def skeleton(path=None, since=None, to=None):
    base, head = commit(since) if since else recorded(), commit(to or "head")
    if not base:
        sys.exit("no base recorded: level the generic files and `record` first, or say --since")
    for s, old, new in skeleton_changes(base, head, manifest(head)):
        mapped = here_as(new)
        if path and path not in (old, new, mapped):
            continue
        print(f"== {new}" + (f" (from {old})" if old != new else "") +
              f"  ->  {'dropped here' if mapped is None else mapped}")
        sys.stdout.writelines(l + "\n" for l in difflib.unified_diff(
            text(blob(base, old)), text(blob(head, new)),
            f"template {base[:7]}: {old}", f"template {head[:7]}: {new}", lineterm=""))
        print()

def diff(path, at=None):
    if not at and not recorded():
        sys.exit("no base recorded: say which template commit to compare with, --at <base>")
    c = commit(at) if at else recorded()
    sys.stdout.writelines(l + "\n" for l in difflib.unified_diff(
        text(tblob(c, path)), text(mine(path)), f"template {c[:7]}: {source(path)}", f"notebook: {path}", lineterm=""))

def take(path, at=None):
    c = commit(at or "head")
    if kind(path, manifest(commit("head"))) != "generic":
        sys.exit(f"{path} is not generic: the notebook owns it, so adapt it by hand")
    data = tblob(c, path)
    if data is None:
        sys.exit(f"not in the template at {c[:7]}: {source(path)}")
    p = VAULT / path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(data)
    print(f"took {path} from {c[:7]}" + (f" ({source(path)})" if source(path) != path else ""))

def verify(staged=False):
    """The guard. A generic file may hold only text the template has given it,
    so a notebook's own material cannot land in one (upstream.md)."""
    if git("rev-parse", "--verify", "--quiet", REF, check=False).returncode:
        sys.exit("the template is not fetched in this checkout: `upstream.py fetch`, then try again")
    head = commit("head")
    entries = manifest(head)
    held = sources()
    stray = lambda f: any(f.startswith(d) for d in held)
    if staged:
        rows = [l.split("\t") for l in git("diff", "--cached", "--name-status", "--no-renames").stdout.decode().splitlines()]
        files = [(f, s) for s, f in rows if kind(f, entries) == "generic" or (stray(f) and s != "D")]
    else:
        here = {f for k, p in entries if k == "generic"
                for f in ([p] if not p.endswith("/") else
                          [str(q.relative_to(VAULT)) for q in (VAULT / p).rglob("*")
                           if q.is_file() and "__pycache__" not in q.parts])}
        files = [(f, "M") for f in sorted(here | {f for f in tree(head) if kind(f, entries) == "generic"}
                                          | set(choices(head)))
                 if kind(f, entries) == "generic"]
        files += [(str(q.relative_to(VAULT)), "M") for d in held if (VAULT / d).is_dir()
                  for q in (VAULT / d).rglob("*") if q.is_file()]
    base = recorded()
    bad = []
    for f, s in files:
        if stray(f):
            bad.append(f"{f}   (a source of the template's choices: a notebook holds only the one it chose,"
                       " as its own file)")
            continue
        if s == "D" or (not staged and not (VAULT / f).exists()):
            # Missing is drift only where the notebook had it: a file new
            # upstream since the base has simply not been taken yet.
            if (tblob(base, f) is not None) if base else tblob(head, f) is not None:
                bad.append(f"{f}   (removed here, still in the template)")
            continue
        sha = git("rev-parse", f":{f}") if staged else git("hash-object", str(VAULT / f))
        if sha.stdout.decode().strip() not in template_blobs(f):
            bad.append(f)
    if bad:
        print(("The notebook's guard refused this commit." if staged else "Drift found.") +
              " These are generic files - the template's, listed in .claude/notebook/manifest.txt -"
              " and they hold text the template never gave them:\n\n  " + "\n  ".join(bad) + "\n\n"
              "Don't commit the edit, and never bypass this with --no-verify. Instead:\n"
              "  1. See it:    python3 -I .scripts/upstream.py diff <file>\n"
              "  2. Decide where it belongs:\n"
              "     - this notebook's own rule or setting: its outlet - .scripts/notebook_config.py,\n"
              "       a script of its own, or the type's declaration (upstream.md, \"The outlets\")\n"
              "     - a fix every notebook needs: the diff is what to ask the template for. Draft an\n"
              "       issue from it, in the template's terms: .claude/notebook/requests.md\n"
              "  3. Undo it:   git restore --staged --worktree -- <file>\n",
              file=sys.stderr)
        sys.exit(1)
    if not staged:
        print("every generic file holds the template's text")

def install_hook():
    p = hook_path()
    if p.exists() and not guarded():
        sys.exit(f"{p} is already a pre-commit hook, and not the guard: "
                 "add `python3 -I .scripts/upstream.py verify --staged` to it by hand")
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(HOOK)
    p.chmod(0o755)
    print(f"guard installed: {p}")

def update(to=None):
    """The generic half of an update, once the guard has kept every generic
    file the template's: nothing to sort, so it is taken whole."""
    base = recorded()
    if not base:
        sys.exit("no base recorded: the first update is the update skill's (upstream.md)")
    target = commit(to or "head")
    me = ".scripts/upstream.py"
    dirty = [l[3:] for l in git("status", "--porcelain").stdout.decode().splitlines()]
    if dirty and not (dirty == [me] and mine(me) == blob(target, me)):   # bar this script, just taken
        sys.exit("the tree is not clean: commit first")
    verify()
    if mine(me) != blob(target, me):
        # The template's own copy of this script does the rest, so a fix to
        # it takes effect in the update that brings it.
        take(me, target)
        sys.stdout.flush()
        os.execv(sys.executable, [sys.executable, "-I", str(VAULT / me), *sys.argv[1:]])
    entries = manifest(target)
    for v, default in unset():
        print(f"{v} is not set in {CONFIG}: taken as {default}, the manifest's default")
    for f in sorted({f for f in tree(target) | tree(base) if kind(f, entries) == "generic"} | set(choices(target))):
        now = tblob(target, f)
        if now is None and mine(f) is not None:
            (VAULT / f).unlink()
            print(f"removed {f}")
        elif now is not None and mine(f) != now:
            take(f, target)
    moved = skeleton_changes(base, target, entries)
    missing = sorted(set(settings((blob(target, CONFIG) or b"").decode())) - set(config()))
    record(target)
    if moved or missing:
        print("\nleft to adapt by hand, with the update skill (upstream.md, step 5):")
        if missing:
            print(f"  {CONFIG}: {', '.join(missing)}")
        print()
        skeleton(since=base, to=target)  # shown now: once recorded, the base is past them
    else:
        print(f"\nnothing to adapt. Commit: Update from notebook-template {base[:7]}..{target[:7]}")

def record(c=None):
    c = commit(c or "head")
    p = VAULT / CONFIG
    if not p.exists():
        sys.exit(f"no {CONFIG} yet: make it from the template's skeleton first")
    body = p.read_text(encoding="utf-8")
    url = git("config", "--get", "notebook.template", check=False).stdout.decode().strip()
    for key, value in (("TEMPLATE_COMMIT", c), ("TEMPLATE", url)):
        line = re.search(rf"^{key} = (.*)$", body, re.M)
        if not line:
            sys.exit(f"{CONFIG} has no {key} line: add it from the template's skeleton")
        if key == "TEMPLATE" and (line.group(1) != "None" or not url):
            continue              # an address already kept is the notebook's choice
        if key == "TEMPLATE" and not re.match(r"^[\w+.-]+://|^[\w.-]+@[\w.-]+:", url):
            print(f"TEMPLATE left unset: {url} is a path on this machine. Set it to an address "
                  "every checkout can reach (upstream.md, step 1)")
            continue
        body = body[:line.start(1)] + f'"{value}"' + body[line.end(1):]
    p.write_text(body, encoding="utf-8")
    print(f"recorded {short(c)}")


if __name__ == "__main__":
    a = sys.argv[1:]
    cmd = a[0] if a else ""
    opt = lambda name: a[a.index(name) + 1] if name in a and a.index(name) + 1 < len(a) else None
    plain = [x for i, x in enumerate(a[1:], 1) if not x.startswith("--") and a[i - 1] not in ("--at", "--since", "--to")]
    if cmd == "fetch":
        fetch(plain[0] if plain else None)
    elif cmd == "status":
        status(opt("--at"))
    elif cmd == "log":
        log(opt("--since"))
    elif cmd == "skeleton":
        skeleton(plain[0] if plain else None, opt("--since"), opt("--to"))
    elif cmd == "diff" and plain:
        diff(plain[0], opt("--at"))
    elif cmd == "take" and plain:
        take(plain[0], opt("--at"))
    elif cmd == "record":
        record(plain[0] if plain else None)
    elif cmd == "update":
        update(opt("--to"))
    elif cmd == "verify":
        verify("--staged" in a)
    elif cmd == "install-hook":
        install_hook()
    else:
        print(__doc__)
        sys.exit(1)
